const TOKEN = $env.HOMELAB_TELEGRAM_BOT_TOKEN, CHAT = String($env.HOMELAB_TELEGRAM_CHAT_ID || '');
const LAN = 'http://192.168.3.201', PVE = 'https://192.168.3.200:8006';
const helpers = this.helpers;
const s = $getWorkflowStaticData('global');
const say = (text) => helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${TOKEN}/sendMessage`, body: { chat_id: CHAT, text, disable_web_page_preview: true }, json: true, timeout: 15000 });
const get = (url, opts = {}) => helpers.httpRequest({ url, json: true, timeout: 20000, ...opts });
const safe = async (fn) => { try { return await fn(); } catch (e) { return null; } };
const lagosNow = () => new Date(new Date().toLocaleString('en-US', { timeZone: 'Africa/Lagos' }));
const pad = (n) => String(n).padStart(2, '0');
const ymd = (d) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const hm = (h) => { const m = Math.round(h * 60); return Math.floor(m / 60) ? `${Math.floor(m / 60)} h ${m % 60} min` : `${m % 60} min`; };
const prom = async (expr) => { const r = await get(`${LAN}:9090/api/v1/query`, { qs: { query: expr } }); const v = r?.data?.result?.[0]?.value?.[1]; return v === undefined ? null : Number(v); };
const pveGet = (path) => get(`${PVE}/api2/json${path}`, { headers: { Authorization: `PVEAPIToken=${$env.HOMEPAGE_VAR_PROXMOX_TOKEN_ID}=${$env.HOMEPAGE_VAR_PROXMOX_TOKEN_SECRET}` }, skipSslCertificateValidation: true }).then(r => r.data);
const ghHeaders = (extra = {}) => ({ Authorization: `Bearer ${$env.HOMELAB_GITHUB_TOKEN || ''}`, Accept: 'application/vnd.github+json', 'User-Agent': 'homelab-n8n', ...extra });
const gh = (path, opts = {}) => { const { headers, ...rest } = opts; return helpers.httpRequest({ url: `https://api.github.com${path}`, json: true, timeout: 20000, headers: ghHeaders(headers), ...rest }); };
const REPO = $env.HOMELAB_GITHUB_REPO || 'theOGpython/homelab';

// Weekly maintenance digest: storage trend, monitor health, release watch, open to-dos, update reminder.
const PINNED = [
  { app: 'Immich', repo: 'immich-app/immich', file: 'docker/immich/setup-env.sh', re: /IMMICH_VERSION=(v?[\d.]+)/, major: true },
  { app: 'Nextcloud', repo: 'nextcloud/server', file: 'docker/nextcloud/compose.yaml', re: /nextcloud:(\d+)/, major: true },
  { app: 'Navidrome', repo: 'navidrome/navidrome', file: 'docker/navidrome/compose.yaml', re: /navidrome:(v?[\d.]+)/ },
  { app: 'Dawarich', repo: 'Freika/dawarich', file: 'docker/dawarich/compose.yaml', re: /dawarich:(v?[\d.]+)/ },
  { app: 'Octo', repo: 'winters27/octo', file: 'docker/octo/setup-env.sh', re: /OCTO_RELEASE=([\w.\-]+)/ },
  { app: 'slskd', repo: 'slskd/slskd', file: 'docker/octo/docker-compose.override.yml', re: /slskd:(v?[\d.]+)/ },
  { app: 'gluetun', repo: 'qdm12/gluetun', file: 'docker/media-stack/compose.vpn.yaml', re: /gluetun:(v?[\d.]+)/ },
  { app: 'Linkwarden', repo: 'linkwarden/linkwarden', file: 'docker/linkwarden/compose.yaml', re: /linkwarden:(v?[\d.]+)/ },
];
const norm = (v) => String(v || '').replace(/^v/, '');
const t = lagosNow();
const L = [`🛠️ Weekly homelab check: ${t.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' })}`];

// Storage, with change since last week
const st = await safe(async () => {
  const [pool, ct, node] = await Promise.all([pveGet('/nodes/pve/storage/local-lvm/status'), pveGet('/nodes/pve/lxc/201/status/current'), pveGet('/nodes/pve/status')]);
  return { pool: pool.used / pool.total * 100, disk: ct.disk / ct.maxdisk * 100, uptime: node.uptime };
});
if (st) {
  const trend = (now, prev) => prev === undefined ? '' : ` (${now - prev >= 0 ? '+' : ''}${(now - prev).toFixed(0)} pts this week)`;
  const flag = (x) => x >= 85 ? ' 🔴' : x >= 80 ? ' ⚠️' : '';
  L.push('', '💾 Storage', `   Pool ${st.pool.toFixed(0)}%${flag(st.pool)}${trend(st.pool, s.pool)}`, `   Docker disk ${st.disk.toFixed(0)}%${flag(st.disk)}${trend(st.disk, s.disk)}`,
    `   Server up ${Math.floor(st.uptime / 86400)} days`);
  if (st.pool >= 80) L.push('   → Delete watched media (/delete) or remove unused stacks.');
  s.pool = st.pool; s.disk = st.disk;
}

// Monitors (Uptime Kuma public status page)
const slug = $env.HOMEPAGE_VAR_KUMA_SLUG || 'home';
const kuma = await safe(async () => {
  const [page, hb] = await Promise.all([get(`${LAN}:3001/api/status-page/${slug}`), get(`${LAN}:3001/api/status-page/heartbeat/${slug}`)]);
  const names = {}; for (const g of page.publicGroupList || []) for (const m of g.monitorList || []) names[m.id] = m.name;
  const issues = [];
  for (const [id, name] of Object.entries(names)) {
    const beats = hb.heartbeatList?.[id] || [], up = hb.uptimeList?.[`${id}_24`];
    const last = beats[beats.length - 1];
    if (last && last.status === 0) issues.push(`   🔴 ${name}: DOWN now`);
    else if (up !== undefined && up < 0.99) issues.push(`   🟡 ${name}: ${(up * 100).toFixed(1)}% up in the last 24 h`);
  }
  return { total: Object.keys(names).length, issues };
});
if (kuma) L.push('', `📡 Monitors (${kuma.total})`, ...(kuma.issues.length ? kuma.issues : ['   ✅ all healthy']));

// Release watch for pinned apps (current version read from the repo, so it follows your bumps)
const rel = await safe(async () => {
  const updates = [], current = [];
  for (const p of PINNED) {
    const file = await safe(() => gh(`/repos/${REPO}/contents/${p.file}`, { headers: { Accept: 'application/vnd.github.raw' }, json: false }));
    const mine = typeof file === 'string' ? file.match(p.re)?.[1] : null;
    if (!mine) continue;                          // stack not in the repo
    const r = await safe(() => gh(`/repos/${p.repo}/releases/latest`));
    if (!r?.tag_name) continue;
    const newer = p.major ? parseInt(norm(r.tag_name)) > parseInt(norm(mine)) : norm(r.tag_name) !== norm(mine);
    if (newer) updates.push(`   ⬆️ ${p.app}: ${mine} → ${r.tag_name}${/breaking/i.test(r.body || '') ? ' ⚠️ mentions breaking changes' : ''}\n      ${r.html_url}`);
    else current.push(p.app);
  }
  return { updates, current };
});
if (rel) L.push('', '📦 Pinned apps', ...(rel.updates.length ? rel.updates : ['   ✅ all on the latest release']), ...(rel.current.length && rel.updates.length ? [`   Up to date: ${rel.current.join(', ')}`] : []));

// Open to-dos (GitHub issues labelled "todo")
const todos = await safe(() => gh(`/repos/${REPO}/issues`, { qs: { state: 'open', labels: 'todo', per_page: 10 } }));
if (todos) L.push('', `📝 To-dos (${todos.length}${todos.length === 10 ? '+' : ''} open)`, ...(todos.length ? todos.slice(0, 6).map(i => `   #${i.number} ${i.title}`) : ['   🎉 none']));

// Monthly update reminder on the first Sunday
if (t.getDate() <= 7) L.push('', '🗓 First Sunday of the month: time for updates.', '   pct snapshot 201 before-updates → update-stacks.sh → check → pct delsnapshot 201 before-updates');

await say(L.join('\n'));
return [{ json: { sent: true } }];
